#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "vk_asset_store.h"
#include "vk_screen_service.h"
#include "vk_vka1.h"

#ifndef ESP_ERR_NOT_FOUND
#define ESP_ERR_NOT_FOUND 0x105
#endif
#ifndef ESP_ERR_INVALID_RESPONSE
#define ESP_ERR_INVALID_RESPONSE 0x108
#endif
#ifndef ESP_ERR_INVALID_CRC
#define ESP_ERR_INVALID_CRC 0x109
#endif

#define FILE_CAPACITY 32U
#define FILE_BYTES 8192U

typedef struct { char name[VK_ASSET_PATH_BYTES]; uint8_t data[FILE_BYTES]; size_t size; bool used; } file_t;
typedef struct { file_t files[FILE_CAPACITY]; uint64_t now_ms; } fs_t;
typedef struct { uint8_t input[32768]; size_t input_count,input_offset; uint8_t output[65536]; size_t output_count; fs_t *fs; } transport_t;
typedef struct { vk_screen_model_t model; uint16_t *pixels; size_t pixel_count; } render_root_t;
typedef struct { fs_t *fs; vk_display_t *display; void *active; unsigned creates,swaps,destroys,flushes; bool fail_create,fail_flush; } renderer_t;

static file_t *file_find(fs_t *fs,const char *name){for(size_t i=0;i<FILE_CAPACITY;i++)if(fs->files[i].used&&!strcmp(fs->files[i].name,name))return &fs->files[i];return NULL;}
static file_t *file_new(fs_t *fs,const char *name){if(file_find(fs,name))return NULL;for(size_t i=0;i<FILE_CAPACITY;i++)if(!fs->files[i].used){fs->files[i].used=true;snprintf(fs->files[i].name,sizeof(fs->files[i].name),"%s",name);return &fs->files[i];}return NULL;}
static esp_err_t mount_fs(void*c,bool format){(void)c;return format?ESP_FAIL:ESP_OK;}static esp_err_t unmount_fs(void*c){(void)c;return ESP_OK;}static esp_err_t format_fs(void*c){(void)c;return ESP_FAIL;}
static esp_err_t erased_fs(void*c,uint32_t o,uint32_t z,uint8_t h[32],bool*a){(void)c;(void)o;(void)z;memset(h,0,32);*a=false;return ESP_OK;}
static esp_err_t read_fs(void*c,const char*n,size_t o,uint8_t*b,size_t cap,size_t*got){file_t*f=file_find(c,n);if(!f)return ESP_ERR_NOT_FOUND;if(o>f->size)return ESP_ERR_INVALID_STATE;*got=f->size-o<cap?f->size-o:cap;memcpy(b,f->data+o,*got);return ESP_OK;}
static esp_err_t size_fs(void*c,const char*n,size_t*z){file_t*f=file_find(c,n);if(!f)return ESP_ERR_NOT_FOUND;*z=f->size;return ESP_OK;}
static esp_err_t new_fs(void*c,const char*n,const uint8_t*b,size_t z,bool sync){(void)sync;if(z>FILE_BYTES)return ESP_ERR_NO_MEM;file_t*f=file_new(c,n);if(!f)return ESP_ERR_INVALID_STATE;if(z)memcpy(f->data,b,z);f->size=z;return ESP_OK;}
static esp_err_t rewrite_fs(void*c,const char*n,const uint8_t*b,size_t z,bool sync){(void)sync;file_t*f=file_find(c,n);if(!f)f=file_new(c,n);if(!f||z>FILE_BYTES)return ESP_ERR_NO_MEM;if(z)memcpy(f->data,b,z);f->size=z;return ESP_OK;}
static esp_err_t append_fs(void*c,const char*n,size_t o,const uint8_t*b,size_t z,bool sync){(void)sync;file_t*f=file_find(c,n);if(!f||f->size!=o||o+z>FILE_BYTES)return ESP_ERR_INVALID_STATE;memcpy(f->data+o,b,z);f->size+=z;return ESP_OK;}
static esp_err_t truncate_fs(void*c,const char*n,size_t z,bool sync){(void)sync;file_t*f=file_find(c,n);if(!f||z>f->size)return ESP_ERR_INVALID_STATE;f->size=z;return ESP_OK;}
static esp_err_t remove_fs(void*c,const char*n){file_t*f=file_find(c,n);if(!f)return ESP_ERR_NOT_FOUND;memset(f,0,sizeof(*f));return ESP_OK;}
static esp_err_t list_fs(void*c,const char*p,char names[][VK_ASSET_PATH_BYTES],size_t cap,size_t*count){fs_t*fs=c;*count=0;for(size_t i=0;i<FILE_CAPACITY;i++)if(fs->files[i].used&&(!strcmp(p,"/")||!strncmp(fs->files[i].name,p,strlen(p)))){if(*count==cap)return ESP_ERR_NO_MEM;snprintf(names[(*count)++],VK_ASSET_PATH_BYTES,"%s",fs->files[i].name);}return ESP_OK;}
static esp_err_t free_fs(void*c,uint32_t*out){(void)c;*out=100000;return ESP_OK;}
static const vk_asset_fs_ops_t fs_ops={mount_fs,unmount_fs,format_fs,erased_fs,read_fs,size_fs,new_fs,rewrite_fs,append_fs,truncate_fs,remove_fs,list_fs,free_fs};

static void hex_sha(const uint8_t digest[32],char output[65]){static const char h[]="0123456789abcdef";for(size_t i=0;i<32;i++){output[i*2]=h[digest[i]>>4];output[i*2+1]=h[digest[i]&15];}output[64]=0;}
static bool parse_hex(const char *text,uint8_t out[32]){if(!text||strlen(text)!=64)return false;for(size_t i=0;i<32;i++){unsigned a=text[i*2]>='a'?text[i*2]-'a'+10:text[i*2]-'0',b=text[i*2+1]>='a'?text[i*2+1]-'a'+10:text[i*2+1]-'0';if(a>15||b>15)return false;out[i]=(uint8_t)((a<<4)|b);}return true;}
static esp_err_t validate_asset(void*c,const char*n,const uint8_t expected[32],uint32_t exact,vk_asset_kind_t kind){fs_t*fs=c;file_t*f=file_find(fs,n);if(!f||f->size!=exact)return ESP_ERR_INVALID_SIZE;vk_vka1_limits_t limits={.max_frames=64,.min_frame_ms=10,.max_frame_ms=60000,.max_container_bytes=4096,.max_decoded_bytes=243104};vk_vka1_info_t info;vk_vka1_result_t r=vk_vka1_validate(f->data,f->size,&limits,&info);if(r!=VK_VKA1_OK)return ESP_ERR_INVALID_RESPONSE;if(memcmp(info.sha256,expected,32))return ESP_ERR_INVALID_CRC;if((kind==VK_ASSET_KIND_IMAGE&&info.kind!=VK_VKA1_IMAGE)||(kind==VK_ASSET_KIND_ANIMATION&&info.kind!=VK_VKA1_ANIMATION))return ESP_ERR_INVALID_RESPONSE;return ESP_OK;}
static esp_err_t validate_revision(void*c,uint32_t revision,uint32_t previous,const uint8_t*a,size_t az,const uint8_t*s,size_t sz){(void)c;char needle[64];int n=snprintf(needle,sizeof(needle),"\"previous_revision\":%u,\"revision\":%u,\"schema\":1}",(unsigned)previous,(unsigned)revision);if(n<=0||az<(size_t)n||sz<(size_t)n||memcmp(a+az-(size_t)n,needle,(size_t)n)||memcmp(s+sz-(size_t)n,needle,(size_t)n))return ESP_ERR_INVALID_RESPONSE;return ESP_OK;}
static uint64_t clock_ms(void*c){return ((fs_t*)c)->now_ms;}

static esp_err_t resolve(void*c,const char*sha,vk_screen_asset_info_t*info){renderer_t*r=c;uint8_t digest[32];if(!parse_hex(sha,digest))return ESP_ERR_INVALID_ARG;char path[VK_ASSET_PATH_BYTES];snprintf(path,sizeof(path),"/assets/%s.vka",sha);file_t*f=file_find(r->fs,path);if(!f)return ESP_ERR_NOT_FOUND;vk_vka1_limits_t limits={64,10,60000,4096,243104};vk_vka1_info_t parsed;if(vk_vka1_validate(f->data,f->size,&limits,&parsed)!=VK_VKA1_OK)return ESP_ERR_INVALID_RESPONSE;uint8_t*copy=malloc(f->size);if(!copy)return ESP_ERR_NO_MEM;memcpy(copy,f->data,f->size);*info=(vk_screen_asset_info_t){parsed.kind,parsed.width,parsed.height,parsed.frame_count,parsed.decoded_bytes_per_frame,copy,f->size};return ESP_OK;}
static void release_asset(void*c,vk_screen_asset_info_t*info){(void)c;free((void*)info->container);info->container=NULL;}
static esp_err_t renderer_lock(void*c){(void)c;return ESP_OK;}static void renderer_unlock(void*c){(void)c;}
static esp_err_t create_root(void*c,const vk_screen_model_t*m,void**root){renderer_t*r=c;r->creates++;if(r->fail_create)return ESP_FAIL;render_root_t*x=calloc(1,sizeof(*x));if(!x)return ESP_ERR_NO_MEM;x->model=*m;for(uint16_t i=0;i<m->object_count;i++)if(m->objects[i].type==VK_SCREEN_OBJECT_IMAGE||m->objects[i].type==VK_SCREEN_OBJECT_PET){vk_screen_asset_info_t info={0};esp_err_t e=resolve(r,m->objects[i].sha256,&info);if(e!=ESP_OK){free(x);return e;}x->pixel_count=(size_t)info.width*info.height;x->pixels=malloc(info.decoded_bytes_per_frame);if(!x->pixels||vk_vka1_decode_frame(info.container,info.container_bytes,0,x->pixels,x->pixel_count)!=VK_VKA1_OK){release_asset(r,&info);free(x->pixels);free(x);return ESP_ERR_INVALID_RESPONSE;}release_asset(r,&info);}uint32_t token=0;esp_err_t e=vk_display_begin_flush_token(r->display,0,0,1,1,2,&token);if(e==ESP_OK){r->flushes++;e=vk_display_complete_flush_token(r->display,token,r->fail_flush?ESP_FAIL:ESP_OK);}if(e!=ESP_OK){free(x->pixels);free(x);return e;}*root=x;return ESP_OK;}
static esp_err_t swap_root(void*c,void*root,void**old){renderer_t*r=c;*old=r->active;r->active=root;r->swaps++;return ESP_OK;}static void destroy_root(void*c,void*root){renderer_t*r=c;if(root){render_root_t*x=root;free(x->pixels);free(x);r->destroys++;}}

static esp_err_t install_t(void*c){(void)c;return ESP_OK;}static esp_err_t uninstall_t(void*c){(void)c;return ESP_OK;}static int read_t(void*c,uint8_t*b,size_t cap,uint32_t timeout){(void)timeout;transport_t*t=c;size_t n=t->input_count-t->input_offset;if(n>cap)n=cap;memcpy(b,t->input+t->input_offset,n);t->input_offset+=n;return(int)n;}static int write_t(void*c,const uint8_t*b,size_t n,uint32_t timeout){(void)timeout;transport_t*t=c;if(t->output_count+n>sizeof(t->output))return-1;memcpy(t->output+t->output_count,b,n);t->output_count+=n;return(int)n;}static uint64_t now_t(void*c){return ((transport_t*)c)->fs->now_ms;}static void lock_t(void*c){(void)c;}static void unlock_t(void*c){(void)c;}
static void queue_frame(transport_t*t,uint8_t type,const uint8_t*b,size_t n){assert(n<=4092&&t->input_count+n+4<=sizeof(t->input));t->input[t->input_count++]=1;t->input[t->input_count++]=type;t->input[t->input_count++]=(uint8_t)n;t->input[t->input_count++]=(uint8_t)(n>>8);memcpy(t->input+t->input_count,b,n);t->input_count+=n;}
static void queue_json(transport_t*t,const char*j){queue_frame(t,VK_USB_FRAME_TYPE_JSON,(const uint8_t*)j,strlen(j));}
static void drain(vk_usb_service_t*s,transport_t*t){size_t guard=0;while(t->input_offset<t->input_count){assert(vk_usb_service_poll(s)==ESP_OK);assert(++guard<10000);}t->input_count=t->input_offset=0;}
static uint8_t*load_file(const char*path,size_t*size){FILE*f=fopen(path,"rb");assert(f);assert(fseek(f,0,SEEK_END)==0);long n=ftell(f);assert(n>0&&n<=4096);rewind(f);uint8_t*b=malloc((size_t)n);assert(b&&fread(b,1,(size_t)n,f)==(size_t)n);fclose(f);*size=(size_t)n;return b;}

