 fs_t fs={0};vk_asset_store_config_t sc={.fs=&fs_ops,.fs_context=&fs,.validate_vka1=validate_asset,.vka1_context=&fs,.validate_revision=validate_revision,.partition_offset=0xa20000,.partition_size=0x5e0000,.reserve_bytes=1,.max_asset_bytes=4096,.max_assets=64};vk_asset_store_t store;assert(vk_asset_store_init(&store,&sc)==ESP_OK);assert(vk_asset_store_mount(&store)==ESP_OK);
