 vk_screen_service_t screen_service;vk_screen_service_readiness_t ready={true,true,true,true,true,true,true};assert(vk_screen_service_init(&screen_service,&store,&transfer,&screen,&display,&ready)==ESP_OK);
 transport_t transport={.fs=&fs};vk_usb_transport_ops_t ops={install_t,uninstall_t,read_t,write_t,now_t,lock_t,unlock_t,&transport};vk_usb_identity_t identity={"vibe_keyboard","test","VS-RAM"};vk_usb_service_policy_t policy={false};vk_usb_service_t*usb=calloc(1,vk_usb_service_size());assert(usb&&vk_usb_service_init(usb,&ops,&identity,&policy)==ESP_OK);vk_usb_capability_provider_registration_t caps;vk_usb_asset_handler_registration_t assets;vk_usb_screen_handler_registration_t screens;vk_usb_widget_handler_registration_t widgets;vk_screen_service_registrations(&screen_service,&caps,&assets,&screens,&widgets);assert(vk_usb_service_register_capability_provider(usb,&caps)==ESP_OK);assert(vk_usb_service_register_asset_handler(usb,&assets)==ESP_OK);assert(vk_usb_service_register_screen_handler(usb,&screens)==ESP_OK);assert(vk_usb_service_register_widget_handler(usb,&widgets)==ESP_OK);assert(vk_usb_service_start(usb)==ESP_OK);
 queue_json(&transport,"{\"event\":\"transport\",\"kind\":\"usb\"}");drain(usb,&transport);queue_json(&transport,"{\"event\":\"get_device_info\"}");drain(usb,&transport);uint32_t epoch=vk_usb_service_epoch(usb);assert(epoch!=0);
 char json[1200];snprintf(json,sizeof(json),"{\"event\":\"vk_asset_begin\",\"transfer_id\":7,\"sha256\":\"%s\",\"total_bytes\":%u,\"kind\":\"image\"}",hash,(unsigned)asset_bytes);queue_json(&transport,json);drain(usb,&transport);vk_usb_asset_command_t tuple;uint32_t next=0;assert(vk_asset_transfer_get_state(&transfer,7,epoch,1,&tuple,&next)==ESP_OK&&next==0);
