 /* Candidate and flush failures preserve the durable/current root. */renderer.fail_create=true;char failed[1200];snprintf(failed,sizeof(failed),"{\"assets\":{\"assets\":[{\"bytes\":%u,\"kind\":\"image\",\"sha256\":\"%s\"}]},\"event\":\"vk_screen_commit\",\"expected_revision\":1,\"revision\":2,\"screen\":{\"configured_mode\":\"image\",\"image\":{\"background_rgb888\":0,\"fit\":\"contain\",\"sha256\":\"%s\"},\"layout\":null,\"pet\":null}}",(unsigned)asset_bytes,hash,hash);queue_json(&transport,failed);drain(usb,&transport);assert(screen.current.revision==1&&store.selected_revision==1&&renderer.swaps==1);renderer.fail_create=false;
